algorithms.pseudocode:
onAck(off):
  if off < cursor: return            -- duplicate ack
  acked.addRange(off, off)           -- merges adjacent ranges
  outstanding.remove(off)
  while acked.first().start == cursor:
     r = acked.popFirst()
     cursor = r.end + 1
  -- persist (cursor, acked) every 1s

onTimer(now):
  for off in outstanding.expired(now):
     attempts[off] += 1
     if attempts[off] > max: publishDLQ(off); onAck(off)
     else: redeliverable.push(off)
